def body(handle, i):
    d = P2[handle]
    g = lambda k: d[k][i]
    sep = '：' if i in (0, 2) else ': '
    li = ''.join('<li>%s%s%s</li>' % (H2[k][i], sep, g(k)) for k in ['mat', 'el', 'land', 'bless'])
    return ('<p><em>%s</em></p><h3>%s</h3><p>%s</p><p>%s</p><h3>%s</h3><p>%s</p><h3>%s</h3><p>%s</p><h3>%s</h3><ul>%s</ul><h3>%s</h3><p>%s</p><p><small>%s</small></p>'
            % (g('tag'), H2['origin'][i], g('o1'), g('o2'), H2['design'][i], g('design'), H2['meaning'][i], g('meaning'),
               H2['piece'][i], li, H2['wear'][i], g('wear'), DISC[i]))
